styles.css.data:
:root {
  --navy-950: #050D26;
  --navy-900: #0A1845;
  --navy-800: #0D1F5A;
  --navy-700: #173282;
  --navy-600: #2244A8;
  --navy-100: #E6EDFF;
  --navy-50: #F4F7FF;

  --orange-600: #D97706;
  --orange-500: #F38B1C;
  --orange-400: #FB923C;
  --orange-100: #FEF3C7;
  --orange-50: #FFFBEB;

  --electric-600: #0062D6;
  --electric-500: #0076FF;
  --electric-100: #E0F0FF;

  --bg-page: #F1F5F9;
  --bg-surface: #FFFFFF;
  --bg-subtle: #F8FAFC;
  --bg-muted: #E2E8F0;

  --text-primary: #0F172A;
  --text-secondary: #334155;
  --text-muted: #64748B;

  --border-light: #E2E8F0;
  --border-strong: #CBD5E1;

  --emerald-700: #047857;
  --emerald-600: #059669;
  --emerald-100: #D1FAE5;
  --emerald-50: #ECFDF5;

  --amber-700: #B45309;
  --amber-100: #FEF3C7;
  --amber-50: #FFFBEB;

  --blue-700: #1D4ED8;
  --blue-100: #DBEAFE;

  --rose-700: #BE123C;
  --rose-100: #FFE4E6;

  --purple-700: #6D28D9;
  --purple-100: #EDE9FE;

  --shadow-xs: 0 1px 2px rgba(10, 24, 69, 0.05);
  --shadow-sm: 0 2px 10px rgba(10, 24, 69, 0.06);
  --shadow-md: 0 8px 24px rgba(10, 24, 69, 0.1);
  --shadow-lg: 0 20px 40px rgba(5, 13, 38, 0.22);

  --font-sans: 'Heebo', 'Assistant', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  min-height: 100dvh;
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 14.5px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* =========================================================================
 * 1. MOBILE-FIRST BASE LAYOUT (320px - 959px)
 * ========================================================================= */
.app-layout {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

/* Desktop Sidebar is hidden on mobile; Bottom Nav is primary on mobile */
.desktop-sidebar {
  display: none;
}

.viewport-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Mobile-First Sticky App Bar */
.app-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-light);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  box-shadow: var(--shadow-xs);
}

.header-brand-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.mobile-logos-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: 999px;
  padding: 3px 7px;
  flex-shrink: 0;
}

.hdr-lev-logo {
  width: 26px;
  height: 26px;
  object-fit: contain;
}

.hdr-divider {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 700;
}

.hdr-okonski-box {
  background: var(--navy-950);
  border-radius: 999px;
  padding: 2px 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hdr-okonski-logo {
  height: 18px;
  width: auto;
  object-fit: contain;
}

.header-titles {
  min-width: 0;
  flex: 1;
}

.header-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--navy-900);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}

.header-subtitle {
  display: none;
  font-size: 12.5px;
  color: var(--text-muted);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.sync-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  background: var(--emerald-50);
  border: 1px solid #A7F3D0;
  color: var(--emerald-700);
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 800;
  cursor: pointer;
}

.pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10B981;
  box-shadow: 0 0 0 2.5px rgba(16, 185, 129, 0.25);
  flex-shrink: 0;
}

.sync-label {
  display: none;
}

.lang-toggle {
  display: inline-flex;
  background: var(--bg-muted);
  padding: 2px;
  border-radius: 9px;
}

.lang-opt {
  border: none;
  background: transparent;
  padding: 5px 10px;
  border-radius: 7px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 800;
  color: var(--text-secondary);
  cursor: pointer;
}

.lang-opt.active {
  background: var(--navy-800);
  color: #FFFFFF;
}

/* Main Content Area (Mobile First Padding + Safe Bottom Space) */
.app-main {
  padding: 12px 12px calc(82px + env(safe-area-inset-bottom, 0px));
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
}

/* Mobile-First Hero Card */
.hero-card {
  background: linear-gradient(135deg, var(--navy-900) 0%, var(--navy-800) 100%);
  color: #FFFFFF;
  border-radius: 16px;
  padding: 16px;
  margin-bottom: 14px;
  box-shadow: var(--shadow-sm);
}

.hero-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.hero-brand-pair {
  display: flex;
  align-items: center;
  gap: 10px;
}

.hero-lev-logo {
  width: 48px;
  height: 48px;
  background: #FFFFFF;
  border-radius: 50%;
  padding: 2px;
  box-shadow: 0 0 0 2px var(--orange-500);
  flex-shrink: 0;
  object-fit: contain;
}

.hero-okonski-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(5, 13, 38, 0.8);
  border: 1px solid rgba(0, 118, 255, 0.45);
  border-radius: 10px;
  padding: 5px 9px;
}

.hero-okonski-logo {
  height: 28px;
  width: auto;
  object-fit: contain;
}

.hero-okonski-text {
  font-size: 11px;
  line-height: 1.2;
}

.hero-okonski-text strong {
  display: block;
  color: #FFFFFF;
  font-size: 11.5px;
}

.hero-okonski-text span {
  color: #93C5FD;
}

.hero-title {
  font-size: 17px;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 4px;
}

.hero-desc {
  font-size: 12.8px;
  color: rgba(255, 255, 255, 0.82);
  line-height: 1.45;
}

.hero-meta-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 12px;
}

.meta-pill {
  background: rgba(255, 255, 255, 0.11);
  padding: 4px 10px;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.95);
}

.meta-pill strong {
  color: var(--orange-400);
}

/* 2x3 Mobile-First KPI Grid */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.kpi-tile {
  background: var(--bg-surface);
  border-radius: 14px;
  padding: 13px 14px;
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-xs);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.15s ease;
}

.kpi-tile:active {
  transform: scale(0.98);
}

.kpi-tile::before {
  content: '';
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  width: 3.5px;
  height: 100%;
  background: var(--navy-800);
}

.kpi-tile.accent-orange::before { background: var(--orange-500); }
.kpi-tile.accent-emerald::before { background: var(--emerald-600); }
.kpi-tile.accent-blue::before { background: var(--electric-500); }
.kpi-tile.accent-purple::before { background: var(--purple-700); }

.kpi-tile-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.kpi-tile-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-secondary);
  line-height: 1.25;
}

.kpi-tile-num {
  font-size: 25px;
  font-weight: 900;
  color: var(--navy-900);
  margin: 6px 0 2px;
  line-height: 1;
}

.kpi-tile-sub {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.25;
}

/* Visual Progress Card */
.progress-card {
  background: var(--bg-surface);
  border-radius: 14px;
  border: 1px solid var(--border-light);
  padding: 14px 16px;
  margin-bottom: 14px;
  box-shadow: var(--shadow-xs);
}

.progress-bar-track {
  height: 11px;
  background: var(--bg-muted);
  border-radius: 999px;
  overflow: hidden;
  display: flex;
  margin: 10px 0;
}

.seg-completed { background: var(--emerald-600); }
.seg-inprogress { background: var(--electric-500); }
.seg-approval { background: var(--orange-500); }
.seg-pending { background: #CBD5E1; }

.progress-legend {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px 10px;
  font-size: 11.8px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: var(--text-secondary);
}

.legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* Dashboard Section Panels */
.overview-grid {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.section-card {
  background: var(--bg-surface);
  border-radius: 14px;
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-xs);
  overflow: hidden;
}

.section-card-head {
  padding: 13px 15px;
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.section-card-title {
  font-size: 14.5px;
  font-weight: 800;
  color: var(--navy-900);
}

.section-card-body {
  padding: 13px 15px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Sticky / Swipeable Filter & Search Bar */
.filter-bar {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: 14px;
  padding: 12px;
  margin-bottom: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: var(--shadow-xs);
}

.pills-scroll {
  display: flex;
  align-items: center;
  gap: 7px;
  overflow-x: auto;
  padding-bottom: 2px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.pills-scroll::-webkit-scrollbar {
  display: none;
}

.pill-btn {
  border: 1px solid var(--border-light);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  padding: 7px 13px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 12.8px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  flex-shrink: 0;
}

.pill-btn.active {
  background: var(--navy-800);
  border-color: var(--navy-800);
  color: #FFFFFF;
}

.search-actions-row {
  display: flex;
  gap: 8px;
}

.search-box {
  flex: 1;
  min-width: 0;
  padding: 9px 13px;
  border-radius: 10px;
  border: 1px solid var(--border-strong);
  font-family: inherit;
  font-size: 16px;
  background: var(--bg-subtle);
  color: var(--text-primary);
}

.search-box:focus {
  outline: 2px solid var(--electric-500);
  background: #FFFFFF;
  border-color: transparent;
}

/* Purpose-Built Mobile-First Task Cards */
.cards-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.task-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: 14px;
  padding: 14px 15px;
  box-shadow: var(--shadow-xs);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.task-id-group {
  display: flex;
  align-items: center;
  gap: 7px;
}

.task-num-tag {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-muted);
}

.task-title {
  font-size: 15.5px;
  font-weight: 800;
  color: var(--navy-900);
  line-height: 1.3;
}

.task-desc {
  font-size: 13.5px;
  color: var(--text-secondary);
  line-height: 1.45;
}

.task-callout {
  background: var(--bg-subtle);
  border-inline-start: 3px solid var(--navy-700);
  padding: 8px 11px;
  border-radius: 8px;
  font-size: 12.8px;
}

.task-callout.deliverable {
  background: #EFF6FF;
  border-inline-start-color: var(--electric-500);
  color: var(--navy-900);
}

.task-callout-label {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text-muted);
  display: block;
  margin-bottom: 2px;
}

.task-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border-light);
}

.status-select {
  flex: 1;
  padding: 7px 10px;
  border-radius: 9px;
  border: 1px solid var(--border-strong);
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 800;
  background: var(--bg-subtle);
  color: var(--navy-900);
  min-height: 38px;
}

/* Purpose-Built Mobile-First School Cards */
.school-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: 14px;
  box-shadow: var(--shadow-xs);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.school-head {
  padding: 14px 15px 11px;
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.school-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: var(--navy-800);
  color: #FFFFFF;
  font-size: 12px;
  font-weight: 800;
  flex-shrink: 0;
}

.school-title {
  font-size: 15.5px;
  font-weight: 800;
  color: var(--navy-900);
  line-height: 1.3;
}

.school-loc {
  font-size: 12.5px;
  color: var(--text-muted);
  margin-top: 2px;
}

.school-body {
  padding: 13px 15px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.quick-contacts-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.q-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  font-size: 12.5px;
  font-weight: 700;
  color: var(--navy-800);
  text-decoration: none;
  cursor: pointer;
}

/* Collapsible Outreach Message Accordion */
.msg-accordion {
  border: 1px solid var(--navy-100);
  background: var(--navy-50);
  border-radius: 10px;
  overflow: hidden;
}

.msg-accordion summary {
  padding: 9px 12px;
  font-size: 12.8px;
  font-weight: 800;
  color: var(--navy-800);
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.msg-accordion summary::-webkit-details-marker {
  display: none;
}

.msg-accordion-content {
  padding: 10px 12px 12px;
  border-top: 1px solid var(--navy-100);
  background: #FFFFFF;
}

.msg-text-box {
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
  max-height: 180px;
  overflow-y: auto;
  color: var(--text-primary);
  margin-top: 8px;
}

.school-foot {
  padding: 11px 15px;
  background: var(--bg-subtle);
  border-top: 1px solid var(--border-light);
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.school-foot .btn {
  flex: 1;
  min-width: calc(50% - 6px);
}

/* Compact Athletic Group Slot Cards */
.athletic-slot-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  box-shadow: var(--shadow-xs);
}

.athletic-slot-card.populated {
  flex-direction: column;
  align-items: stretch;
}

/* Notice Banner */
.notice-banner {
  background: var(--amber-50);
  border: 1px solid #FCD34D;
  border-inline-start: 4px solid var(--orange-500);
  border-radius: 12px;
  padding: 11px 13px;
  margin-bottom: 12px;
  font-size: 12.5px;
  color: #78350F;
  line-height: 1.45;
}

/* Badges & Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 13px;
  border-radius: 9px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  border: 1px solid transparent;
  text-decoration: none;
  white-space: nowrap;
  min-height: 38px;
}

.btn-primary { background: var(--navy-800); color: #FFFFFF; }
.btn-emerald { background: var(--emerald-600); color: #FFFFFF; }
.btn-outline { background: #FFFFFF; border-color: var(--border-strong); color: var(--text-primary); }
.btn-sm { padding: 6px 10px; font-size: 12px; min-height: 34px; }

.status-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}

.status-completed, .status-approved { background: var(--emerald-100); color: var(--emerald-700); }
.status-inprogress, .status-sent { background: var(--blue-100); color: var(--blue-700); }
.status-approval { background: var(--amber-100); color: var(--amber-700); }
.status-notstarted { background: var(--bg-muted); color: var(--text-secondary); }
.status-onhold { background: #F3E8FF; color: #7E22CE; border: 1px solid #E9D5FF; }
.status-donotduplicate { background: var(--rose-100); color: var(--rose-700); }
.status-relationship { background: var(--purple-100); color: var(--purple-700); }

.task-dates-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.task-date-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  color: var(--text-secondary);
}

.task-date-chip.overdue {
  background: var(--rose-100);
  border-color: #FECDD3;
  color: var(--rose-700);
}

.task-date-chip.followup {
  background: var(--amber-50);
  border-color: #FDE68A;
  color: var(--amber-700);
}

.priority-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 800;
  background: var(--navy-100);
  color: var(--navy-800);
}

.priority-P1, .priority-P2 { background: var(--rose-100); color: var(--rose-700); }
.priority-P3, .priority-P4 { background: var(--amber-100); color: var(--amber-700); }

/* Native Mobile Bottom Navigation Bar */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: rgba(10, 24, 69, 0.98);
  backdrop-filter: blur(16px);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding: 5px 6px calc(5px + env(safe-area-inset-bottom, 0px));
  display: flex;
  justify-content: space-around;
  align-items: center;
  box-shadow: 0 -6px 20px rgba(5, 13, 38, 0.2);
}

.tab-btn {
  flex: 1;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.62);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 5px 2px;
  border-radius: 10px;
  font-family: inherit;
  cursor: pointer;
  min-height: 48px;
}

.tab-btn.active {
  color: #FFFFFF;
  background: rgba(243, 139, 28, 0.22);
}

.tab-icon-wrap {
  position: relative;
  width: 24px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.tab-icon-wrap svg {
  width: 20px;
  height: 20px;
}

.tab-btn.active svg {
  stroke: var(--orange-400);
}

.tab-badge {
  position: absolute;
  top: -4px;
  inset-inline-end: -11px;
  background: var(--electric-500);
  color: #FFFFFF;
  font-size: 9.5px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 999px;
  line-height: 1.15;
}

.tab-badge.badge-orange {
  background: var(--orange-500);
}

.tab-label {
  font-size: 11px;
  font-weight: 800;
}

/* Bottom-Sheet Modal (Mobile First) */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 13, 38, 0.6);
  backdrop-filter: blur(3px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  z-index: 100;
}

.modal-backdrop.hidden {
  display: none;
}

.modal-sheet {
  background: var(--bg-surface);
  width: 100%;
  max-width: 720px;
  max-height: 92dvh;
  border-radius: 20px 20px 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.sheet-handle {
  width: 40px;
  height: 4px;
  background: rgba(255, 255, 255, 0.35);
  border-radius: 999px;
  margin: 8px auto -4px;
  z-index: 2;
}

.modal-header {
  padding: 14px 18px;
  background: var(--navy-900);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.modal-title {
  font-size: 16px;
  font-weight: 800;
}

.modal-close-btn {
  background: rgba(255, 255, 255, 0.14);
  border: none;
  color: #FFFFFF;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.modal-body {
  padding: 16px 16px calc(20px + env(safe-area-inset-bottom, 0px));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.form-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-secondary);
}

.form-control {
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border-strong);
  font-family: inherit;
  font-size: 16px;
  color: var(--text-primary);
  background: var(--bg-surface);
  min-height: 44px;
}

textarea.form-control {
  min-height: 95px;
  resize: vertical;
}

.modal-actions {
  display: flex;
  flex-direction: column-reverse;
  gap: 8px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--border-light);
}

.modal-actions .btn {
  width: 100%;
  min-height: 44px;
  font-size: 14.5px;
}

.msg-lang-tabs {
  display: inline-flex;
  background: var(--bg-muted);
  padding: 2px;
  border-radius: 7px;
}

.msg-lang-tab {
  border: none;
  background: transparent;
  padding: 4px 10px;
  border-radius: 5px;
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 800;
  cursor: pointer;
}

.msg-lang-tab.active {
  background: var(--navy-800);
  color: #FFFFFF;
}

.toast-container {
  position: fixed;
  bottom: calc(70px + env(safe-area-inset-bottom, 0px));
  left: 14px;
  right: 14px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.toast {
  background: var(--navy-900);
  color: #FFFFFF;
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: var(--shadow-md);
  border-inline-start: 4px solid var(--orange-500);
  font-size: 13.5px;
  font-weight: 700;
  text-align: center;
}

/* =========================================================================
 * 2. TABLET EXPANSION (min-width: 640px)
 * ========================================================================= */
@media (min-width: 640px) {
  .app-main {
    padding: 18px 20px 90px;
  }
  .kpi-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }
  .progress-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 18px;
  }
  .cards-list {
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
  }
  .school-foot .btn {
    min-width: auto;
    flex: initial;
  }
  .form-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .form-group.full-width {
    grid-column: 1 / -1;
  }
  .modal-backdrop {
    align-items: center;
    padding: 20px;
  }
  .modal-sheet {
    border-radius: 18px;
  }
  .sheet-handle {
    display: none;
  }
  .modal-actions {
    flex-direction: row;
    justify-content: flex-end;
  }
  .modal-actions .btn {
    width: auto;
  }
  .sync-label {
    display: inline;
  }
}

/* =========================================================================
 * 3. DESKTOP EXPANSION (min-width: 960px)
 * ========================================================================= */
@media (min-width: 960px) {
  .app-layout {
    flex-direction: row;
  }
  .bottom-nav {
    display: none;
  }
  .mobile-logos-pill {
    display: none;
  }
  .header-subtitle {
    display: block;
  }
  .app-header {
    padding: 14px 28px;
  }
  .header-title {
    font-size: 20px;
  }
  .app-main {
    padding: 24px 28px 48px;
  }
  .kpi-grid {
    grid-template-columns: repeat(6, 1fr);
  }
  .overview-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
  }
  .filter-bar {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
  .search-actions-row {
    min-width: 360px;
  }
  .toast-container {
    bottom: 24px;
    left: auto;
    right: auto;
    inset-inline-end: 24px;
    width: 340px;
  }

  /* Desktop Sidebar */
  .desktop-sidebar {
    display: flex;
    flex-direction: column;
    width: 280px;
    flex-shrink: 0;
    background: linear-gradient(180deg, var(--navy-900) 0%, var(--navy-950) 100%);
    color: #FFFFFF;
    position: sticky;
    top: 0;
    height: 100dvh;
    border-inline-end: 1px solid rgba(255, 255, 255, 0.08);
  }
  .sidebar-brand {
    padding: 22px 18px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  }
  .sidebar-logo-circle {
    width: 58px;
    height: 58px;
    background: #FFFFFF;
    border-radius: 50%;
    padding: 3px;
    flex-shrink: 0;
    box-shadow: 0 0 0 2px var(--orange-500);
  }
  .sidebar-logo-circle img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }
  .sidebar-brand-text .eyebrow {
    font-size: 10px;
    font-weight: 800;
    color: var(--orange-400);
    text-transform: uppercase;
    display: block;
  }
  .sidebar-brand-text h1 {
    font-size: 18px;
    font-weight: 800;
  }
  .sidebar-brand-text p {
    font-size: 11.5px;
    color: rgba(255, 255, 255, 0.7);
  }
  .sidebar-menu {
    flex: 1;
    padding: 16px 12px;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .nav-btn {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 11px;
    padding: 12px 14px;
    border-radius: 11px;
    border: 1px solid transparent;
    background: transparent;
    color: rgba(255, 255, 255, 0.78);
    font-family: inherit;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    text-align: start;
  }
  .nav-btn svg {
    width: 19px;
    height: 19px;
    color: var(--orange-400);
    flex-shrink: 0;
  }
  .nav-btn span:nth-child(2) {
    flex: 1;
  }
  .nav-btn.active {
    background: rgba(243, 139, 28, 0.22);
    border-color: rgba(243, 139, 28, 0.5);
    color: #FFFFFF;
  }
  .badge-pill {
    background: rgba(255, 255, 255, 0.16);
    padding: 2px 8px;
    border-radius: 999px;
    font-size: 11.5px;
    font-weight: 800;
  }
  .badge-pill.badge-orange {
    background: var(--orange-500);
  }
  .sidebar-footer {
    padding: 14px;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(3, 8, 22, 0.55);
  }
  .manager-badge-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    border-radius: 11px;
    background: rgba(13, 31, 90, 0.75);
    border: 1px solid rgba(0, 118, 255, 0.4);
  }
  .manager-logo-wrap {
    width: 52px;
    height: 42px;
    background: var(--navy-950);
    border-radius: 7px;
    padding: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .manager-logo-wrap img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
  }
  .manager-info {
    display: flex;
    flex-direction: column;
    font-size: 11.5px;
  }
  .manager-tag {
    font-size: 9.5px;
    color: #93C5FD;
    font-weight: 800;
    text-transform: uppercase;
  }
  .manager-sub {
    color: rgba(255, 255, 255, 0.75);
  }
}

/* Owner Badges & Segmented Selector */
.owner-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
}

.owner-ofek {
  background: var(--electric-100);
  color: var(--electric-600);
}

.owner-maccabi {
  background: var(--orange-100);
  color: var(--amber-700);
}

.owner-selector-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.owner-radio-label {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1.5px solid var(--border-strong);
  background: var(--bg-subtle);
  font-size: 14px;
  font-weight: 800;
  color: var(--text-secondary);
  cursor: pointer;
  min-height: 44px;
  transition: all 0.15s ease;
}

.owner-radio-label input {
  display: none;
}

.owner-radio-label:has(input:checked) {
  background: var(--navy-800);
  border-color: var(--navy-800);
  color: #FFFFFF;
  box-shadow: 0 2px 8px rgba(13, 31, 90, 0.22);
}

.owner-filter-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-top: 4px;
  border-top: 1px dashed var(--border-light);
}

.owner-filter-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-muted);
  white-space: nowrap;
}

