class OperationsApp {
  constructor() {
    this.lang = localStorage.getItem('lev_ari_lang') || 'he';
    this.activeSection = 'overview';
    this.data = null;

    this.taskStatusFilter = 'all';
    this.taskOwnerFilter = 'all';
    this.taskSearch = '';

    this.schoolRecordTypeFilter = 'prospect';
    this.schoolSearch = '';
    this.schoolMsgTab = {};

    this.athleticCategoryFilter = 'Running';
    this.athleticSearch = '';
  }

  t(key) {
    return (I18N[this.lang] && I18N[this.lang][key]) || I18N.en[key] || key;
  }

  bf(obj, baseField) {
    if (!obj) return '';
    const primary = obj[`${baseField}_${this.lang}`];
    const fallback = obj[`${baseField}_${this.lang === 'he' ? 'en' : 'he'}`];
    return primary || fallback || obj[baseField] || '';
  }

  getOwnerKey(task) {
    const raw = `${task?.owner_en || ''} ${task?.owner_he || ''}`.toLowerCase();
    if (raw.includes('maccabi') || raw.includes('מכבי') || raw.includes('lev-ari') || raw.includes('לב-ארי')) {
      return 'maccabi';
    }
    return 'ofek';
  }

  formatOwnerBadge(task) {
    const key = this.getOwnerKey(task);
    const label = key === 'maccabi' ? this.t('ownerMaccabi') : this.t('ownerOfek');
    return `<span class="owner-pill owner-${key}">👤 ${this.escapeHtml(label)}</span>`;
  }

  escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  async init() {
    this.applyLanguageAttributes();
    await this.loadBootstrap();
    this.updateShellChrome();
    this.renderCurrentSection();
  }

  async loadBootstrap() {
    const cachedRaw = localStorage.getItem('lev_ari_local_backup');
    const cached = cachedRaw ? JSON.parse(cachedRaw) : null;
    try {
      const res = await fetch('api/bootstrap');
      if (!res.ok) throw new Error('API unreachable');
      const remoteData = await res.json();
      if (
        cached &&
        cached.lastSyncedAt &&
        remoteData.lastSyncedAt &&
        new Date(cached.lastSyncedAt) > new Date(remoteData.lastSyncedAt)
      ) {
        this.data = cached;
      } else {
        this.data = remoteData;
        localStorage.setItem('lev_ari_local_backup', JSON.stringify(this.data));
      }
    } catch {
      if (cached) {
        this.data = cached;
      } else {
        const res = await fetch('data/cloud-db.json');
        this.data = await res.json();
        localStorage.setItem('lev_ari_local_backup', JSON.stringify(this.data));
      }
    }
    this.recomputeSummary();
    this.updateNavBadges();
  }

  recomputeSummary() {
    if (!this.data) return;
    const tasks = this.data.tasks || [];
    const schools = this.data.schools || [];
    const athleticGroups = this.data.athleticGroups || [];

    const totalTasks = tasks.length;
    const tasksInProgress = tasks.filter(t => t.status.toLowerCase() === 'in progress').length;
    const onHoldTasks = tasks.filter(t => t.status.toLowerCase() === 'on hold').length;
    const completedTasks = tasks.filter(t => ['completed', 'done'].includes(t.status.toLowerCase())).length;
    const notStartedTasks = tasks.filter(t => t.status.toLowerCase() === 'not started').length;

    const prospectSchools = schools.filter(s => s.record_type === 'prospect');
    const schoolsResearched = prospectSchools.length;
    const outreachPrepared = schools.filter(
      s => (s.outreach_message_he && s.outreach_message_he.trim().length > 0) ||
           (s.outreach_message_en && s.outreach_message_en.trim().length > 0)
    ).length;

    const pendingSchoolApprovals = schools.filter(s => ['ready for approval', 'pending approval'].includes(s.status.toLowerCase())).length;
    const pendingTaskApprovals = tasks.filter(t => ['ready for approval', 'pending approval'].includes(t.status.toLowerCase())).length;
    const pendingGroupApprovals = athleticGroups.filter(g => ['ready for approval', 'pending approval'].includes(g.status.toLowerCase())).length;

    this.data.summary = {
      totalTasks,
      tasksInProgress,
      onHoldTasks,
      completedTasks,
      notStartedTasks,
      pendingApprovals: pendingSchoolApprovals + pendingTaskApprovals + pendingGroupApprovals,
      pendingSchoolApprovals,
      pendingTaskApprovals,
      schoolsResearched,
      totalSchoolRecords: schools.length,
      outreachPrepared,
      athleticGroupsTotal: athleticGroups.length,
      athleticGroupsResearched: athleticGroups.filter(
        g => (g.club_organization_he && g.club_organization_he.trim().length > 0) ||
             (g.club_organization_en && g.club_organization_en.trim().length > 0)
      ).length
    };
  }

  applyLanguageAttributes() {
    const html = document.documentElement;
    html.lang = this.lang;
    html.dir = this.lang === 'he' ? 'rtl' : 'ltr';

    document.getElementById('lang-btn-he')?.classList.toggle('active', this.lang === 'he');
    document.getElementById('lang-btn-en')?.classList.toggle('active', this.lang === 'en');

    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      el.textContent = this.t(key);
    });
  }

  setLanguage(lang) {
    this.lang = lang === 'en' ? 'en' : 'he';
    localStorage.setItem('lev_ari_lang', this.lang);
    this.applyLanguageAttributes();
    this.updateShellChrome();
    this.renderCurrentSection();
  }

  updateNavBadges() {
    if (!this.data) return;
    const { summary } = this.data;
    const setBadge = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.textContent = val;
    };
    setBadge('nav-badge-tasks', summary.totalTasks);
    setBadge('nav-badge-schools', summary.schoolsResearched);
    setBadge('nav-badge-athletic', summary.athleticGroupsTotal);

    setBadge('mobile-badge-tasks', summary.totalTasks);
    setBadge('mobile-badge-schools', summary.schoolsResearched);
    setBadge('mobile-badge-athletic', summary.athleticGroupsTotal);
  }

  updateShellChrome() {
    const headingMap = {
      overview: ['overviewTitle', 'overviewSubtitle'],
      tasks: ['tasksTitle', 'tasksSubtitle'],
      schools: ['schoolsTitle', 'schoolsSubtitle'],
      athletic: ['athleticTitle', 'athleticSubtitle']
    };
    const [hKey, sKey] = headingMap[this.activeSection] || headingMap.overview;
    const hEl = document.getElementById('page-heading');
    const sEl = document.getElementById('page-subheading');
    if (hEl) hEl.textContent = this.t(hKey);
    if (sEl) sEl.textContent = this.t(sKey);

    document.querySelectorAll('.nav-btn, .tab-btn').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-section') === this.activeSection);
    });
  }

  navigate(section, opts = {}) {
    this.activeSection = section;
    if (opts.schoolFilter) this.schoolRecordTypeFilter = opts.schoolFilter;
    if (opts.taskStatus) this.taskStatusFilter = opts.taskStatus;
    if (opts.athleticCategory) this.athleticCategoryFilter = opts.athleticCategory;
    this.updateShellChrome();
    this.renderCurrentSection();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  formatStatusText(status) {
    const map = {
      'Not started': this.t('statusNotStarted'),
      'In progress': this.t('statusInProgress'),
      'On hold': this.t('statusOnHold'),
      'Ready for approval': this.t('statusReadyForApproval'),
      'Completed': this.t('statusCompleted'),
      'Approved': this.t('statusApproved'),
      'Sent': this.t('statusSent'),
      'Responded': this.t('statusResponded'),
      'Already contacted': this.t('statusAlreadyContacted'),
      'Existing relationship': this.t('statusExistingRelationship'),
      'Not researched': this.t('statusNotResearched'),
      'Researched': this.t('statusResearched')
    };
    return map[status] || status;
  }

  formatStatusBadge(status) {
    const s = (status || '').toLowerCase();
    let cls = 'status-notstarted';
    if (s === 'completed' || s === 'done' || s === 'responded') cls = 'status-completed';
    else if (s === 'approved') cls = 'status-approved';
    else if (s === 'in progress' || s === 'researched' || s === 'sent') cls = 'status-inprogress';
    else if (s === 'on hold') cls = 'status-onhold';
    else if (s === 'ready for approval' || s === 'pending approval') cls = 'status-approval';
    else if (s === 'already contacted') cls = 'status-donotduplicate';
    else if (s === 'existing relationship') cls = 'status-relationship';

    return `<span class="status-badge ${cls}">${this.escapeHtml(this.formatStatusText(status))}</span>`;
  }

  formatDisplayDate(isoDate) {
    if (!isoDate) return '';
    const parts = String(isoDate).split('-');
    if (parts.length !== 3) return isoDate;
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }

  formatTaskDates(task) {
    if (!task) return '';
    const due = (task.due_date || '').trim();
    const followUp = (task.follow_up_date || '').trim();
    if (!due && !followUp) return '';

    const todayIso = new Date().toISOString().slice(0, 10);
    const isCompleted = ['completed', 'done'].includes((task.status || '').toLowerCase());
    const isOverdue = Boolean(due && !isCompleted && due < todayIso);

    return `
      <div class="task-dates-row">
        ${due ? `
          <span class="task-date-chip ${isOverdue ? 'overdue' : ''}">
            📅 ${this.escapeHtml(this.t('colDueDate'))}: ${this.escapeHtml(this.formatDisplayDate(due))}${isOverdue ? ` (${this.escapeHtml(this.t('dueDateOverdue'))})` : ''}
          </span>
        ` : ''}
        ${followUp ? `
          <span class="task-date-chip followup">
            🔔 ${this.escapeHtml(this.t('colFollowUpDate'))}: ${this.escapeHtml(this.formatDisplayDate(followUp))}
          </span>
        ` : ''}
      </div>
    `;
  }

  formatCategoryText(cat) {
    if (cat === 'Running') return this.lang === 'he' ? 'ריצה' : 'Running';
    if (cat === 'Cycling') return this.lang === 'he' ? 'אופניים' : 'Cycling';
    if (cat === 'Triathlon') return this.lang === 'he' ? 'טריאתלון' : 'Triathlon';
    return cat;
  }

  showToast(message) {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => toast.remove(), 2800);
  }

  async copyText(text, toastKey = 'copiedMsgToast') {
    if (!text) return;
    try {
      await navigator.clipboard.writeText(text);
      this.showToast(this.t(toastKey));
    } catch {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
      this.showToast(this.t(toastKey));
    }
  }

  renderCurrentSection() {
    const main = document.getElementById('main-content');
    if (!main || !this.data) return;

    switch (this.activeSection) {
      case 'overview':
        main.innerHTML = this.renderOverview();
        break;
      case 'tasks':
        main.innerHTML = this.renderTasksSection();
        break;
      case 'schools':
        main.innerHTML = this.renderSchoolsSection();
        break;
      case 'athletic':
        main.innerHTML = this.renderAthleticSection();
        break;
      default:
        main.innerHTML = this.renderOverview();
    }
  }

