              </div>
            `).join('')}
          </div>
        </section>

        <!-- Panel 4: Athletic Pipeline -->
        <section class="section-card">
          <div class="section-card-head">
            <h3 class="section-card-title">${this.escapeHtml(this.t('panelAthleticSummaryTitle'))}</h3>
            <button type="button" class="btn btn-sm btn-outline" onclick="window.app.navigate('athletic')">${this.escapeHtml(this.t('viewAllBtn'))}</button>
          </div>
          <div class="section-card-body">
            ${['Running', 'Cycling', 'Triathlon'].map(cat => {
              const catGroups = athleticGroups.filter(g => g.category === cat);
              const researchedCount = catGroups.filter(g => this.bf(g, 'club_organization').trim().length > 0).length;
              return `
                <div style="padding:11px 13px;border:1px solid var(--border-light);border-radius:11px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;background:var(--bg-subtle)" onclick="window.app.navigate('athletic', { athleticCategory: '${cat}' })">
                  <div>
                    <strong style="font-size:14px;color:var(--navy-900)">${this.escapeHtml(this.formatCategoryText(cat))}</strong>
                    <div style="font-size:12px;color:var(--text-muted)">${researchedCount} / ${catGroups.length}</div>
                  </div>
                  <span class="btn btn-sm btn-outline">${this.escapeHtml(this.t('viewAllBtn'))}</span>
                </div>
              `;
            }).join('')}
          </div>
        </section>
      </div>
    `;
  }

  /* =========================================================================
   * 2. MOBILE-FIRST TASK CARDS (ZERO TABLES!)
   * ========================================================================= */
  renderTasksSection() {
    const { tasks } = this.data;
    const filtered = tasks.filter(t => {
      if (this.taskStatusFilter !== 'all' && t.status.toLowerCase() !== this.taskStatusFilter.toLowerCase()) {
        return false;
      }
      if (this.taskOwnerFilter !== 'all' && this.getOwnerKey(t) !== this.taskOwnerFilter) {
        return false;
      }
      if (this.taskSearch) {
        const q = this.taskSearch.toLowerCase();
        const hay = `${t.task_he} ${t.task_en} ${t.description_he} ${t.description_en} ${t.output_results_he} ${t.output_results_en} ${t.next_action_he} ${t.next_action_en} ${t.notes_approval_he} ${t.notes_approval_en} ${t.owner_he} ${t.owner_en} ${t.priority}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    const statuses = [
      { key: 'all', label: `${this.t('filterAll')} (${tasks.length})` },
      { key: 'In progress', label: `${this.t('statusInProgress')} (${tasks.filter(t => t.status.toLowerCase() === 'in progress').length})` },
      { key: 'On hold', label: `${this.t('statusOnHold')} (${tasks.filter(t => t.status.toLowerCase() === 'on hold').length})` },
      { key: 'Not started', label: `${this.t('statusNotStarted')} (${tasks.filter(t => t.status.toLowerCase() === 'not started').length})` },
      { key: 'Ready for approval', label: `${this.t('statusReadyForApproval')} (${tasks.filter(t => t.status.toLowerCase() === 'ready for approval').length})` },
      { key: 'Completed', label: `${this.t('statusCompleted')} (${tasks.filter(t => t.status.toLowerCase() === 'completed').length})` }
    ];

    const owners = [
      { key: 'all', label: this.t('filterAll') },
      { key: 'ofek', label: `${this.t('ownerOfek')} (${tasks.filter(t => this.getOwnerKey(t) === 'ofek').length})` },
      { key: 'maccabi', label: `${this.t('ownerMaccabi')} (${tasks.filter(t => this.getOwnerKey(t) === 'maccabi').length})` }
    ];

    return `
      <div class="filter-bar">
        <div class="pills-scroll">
          ${statuses.map(st => `
            <button type="button" class="pill-btn ${this.taskStatusFilter === st.key ? 'active' : ''}" onclick="window.app.setTaskFilter('${st.key}')">
              ${this.escapeHtml(st.label)}
            </button>
          `).join('')}
        </div>

        <div class="owner-filter-row pills-scroll">
          <span class="owner-filter-label">${this.escapeHtml(this.t('filterByOwner'))}</span>
          ${owners.map(ow => `
            <button type="button" class="pill-btn ${this.taskOwnerFilter === ow.key ? 'active' : ''}" onclick="window.app.setTaskOwnerFilter('${ow.key}')">
              ${this.escapeHtml(ow.label)}
            </button>
          `).join('')}
        </div>

        <div class="search-actions-row">
          <input type="search" class="search-box" placeholder="${this.escapeHtml(this.t('searchPlaceholder'))}" value="${this.escapeHtml(this.taskSearch)}" oninput="window.app.setTaskSearch(this.value)" />
          <button type="button" class="btn btn-primary" onclick="window.app.openTaskModal()">${this.escapeHtml(this.t('addTaskBtn'))}</button>
        </div>
      </div>

      <div class="cards-list">
        ${filtered.map(t => `
          <article class="task-card">
            <div class="task-card-top">
              <div class="task-id-group">
                <span class="task-num-tag">#${t.task_number}</span>
                <span class="priority-badge priority-${this.escapeHtml(t.priority)}">${this.escapeHtml(t.priority)}</span>
                ${this.formatOwnerBadge(t)}
              </div>
              ${this.formatStatusBadge(t.status)}
            </div>

            <div>
              <h3 class="task-title">${this.escapeHtml(this.bf(t, 'task'))}</h3>
              <p class="task-desc" style="margin-top:3px">${this.escapeHtml(this.bf(t, 'description'))}</p>
              ${this.formatTaskDates(t)}
            </div>

            ${this.bf(t, 'output_results') ? `
              <div class="task-callout deliverable">
                <span class="task-callout-label">${this.escapeHtml(this.t('colDeliverable'))}</span>
                ${this.escapeHtml(this.bf(t, 'output_results'))}
              </div>
            ` : ''}

            ${this.bf(t, 'next_action') ? `
              <div class="task-callout">
                <span class="task-callout-label">${this.escapeHtml(this.t('colNextAction'))}</span>
                <strong>${this.escapeHtml(this.bf(t, 'next_action'))}</strong>
              </div>
            ` : ''}

            ${this.bf(t, 'notes_approval') ? `
              <div style="font-size:12.5px;color:var(--text-muted)">
                <strong>${this.escapeHtml(this.t('colNotes'))}:</strong> ${this.escapeHtml(this.bf(t, 'notes_approval'))}
              </div>
            ` : ''}

            <div class="task-card-foot">
              <select class="status-select" onchange="window.app.quickUpdateTaskStatus(${t.id}, this.value)" aria-label="Task Status">
                ${['Not started', 'In progress', 'On hold', 'Ready for approval', 'Completed'].map(opt => `
                  <option value="${opt}" ${t.status.toLowerCase() === opt.toLowerCase() ? 'selected' : ''}>${this.escapeHtml(this.formatStatusText(opt))}</option>
                `).join('')}
              </select>
              <button type="button" class="btn btn-outline" onclick="window.app.openTaskModal(${t.id})">✏️ ${this.escapeHtml(this.t('editBtn'))}</button>
            </div>
          </article>
        `).join('')}
      </div>
    `;
  }

  setTaskFilter(status) {
    this.taskStatusFilter = status;
    this.renderCurrentSection();
  }

  setTaskOwnerFilter(ownerKey) {
    this.taskOwnerFilter = ownerKey;
    this.renderCurrentSection();
  }

  setTaskSearch(val) {
    this.taskSearch = val;
    this.renderCurrentSection();
  }

  async quickUpdateTaskStatus(id, status) {
    try {
      const res = await fetch(`api/tasks/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status })
      });
      if (!res.ok) throw new Error('Static mode');
      this.data = await res.json();
    } catch {
      const t = this.data.tasks.find(x => x.id === id);
      if (t) t.status = status;
      this.recomputeSummary();
    }
    localStorage.setItem('lev_ari_local_backup', JSON.stringify(this.data));
    this.updateNavBadges();
    this.renderCurrentSection();
    this.showToast(this.t('savedToast'));
  }

  /* =========================================================================
   * 3. MOBILE-FIRST SCHOOL OUTREACH CARDS
   * ========================================================================= */
  renderSchoolsSection() {
    const { schools, metadata } = this.data;

    const filtered = schools.filter(s => {
      if (this.schoolRecordTypeFilter !== 'all' && s.record_type !== this.schoolRecordTypeFilter) {
        return false;
      }
      if (this.schoolSearch) {
        const q = this.schoolSearch.toLowerCase();
        const hay = `${s.institution_he} ${s.institution_en} ${s.location_he} ${s.location_en} ${s.relevant_program_he} ${s.relevant_program_en} ${s.decision_maker_he} ${s.decision_maker_en} ${s.verified_email} ${s.verified_phone}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    const recordTabs = [
      { key: 'prospect', label: this.t('schoolTabProspects') },
      { key: 'do_not_duplicate', label: this.t('schoolTabDoNotDuplicate') },
      { key: 'existing_relationship', label: this.t('schoolTabExisting') },
      { key: 'all', label: this.t('schoolTabAll') }
    ];

    const verifyNote = metadata[`schools_verification_note_${this.lang}`] || metadata.schools_verification_note_he;

    return `
      <div class="notice-banner">
        <strong>${this.escapeHtml(this.t('verificationPolicyTitle'))}</strong> ${this.escapeHtml(verifyNote)}
        <div style="margin-top:3px;font-weight:800;color:var(--navy-900)">${this.escapeHtml(this.t('noAutoEmailNotice'))}</div>
      </div>

      <div class="filter-bar">
        <div class="pills-scroll">
          ${recordTabs.map(tab => `
            <button type="button" class="pill-btn ${this.schoolRecordTypeFilter === tab.key ? 'active' : ''}" onclick="window.app.setSchoolTypeFilter('${tab.key}')">
              ${this.escapeHtml(tab.label)}
            </button>
          `).join('')}
        </div>

        <div class="search-actions-row">
          <input type="search" class="search-box" placeholder="${this.escapeHtml(this.t('searchPlaceholder'))}" value="${this.escapeHtml(this.schoolSearch)}" oninput="window.app.setSchoolSearch(this.value)" />
          <button type="button" class="btn btn-primary" onclick="window.app.openSchoolModal()">${this.escapeHtml(this.t('addSchoolBtn'))}</button>
        </div>
      </div>

      <div class="cards-list">
        ${filtered.map(s => {
          const activeMsgTab = this.schoolMsgTab[s.id] || this.lang;
          const currentDraft = activeMsgTab === 'en' ? s.outreach_message_en : s.outreach_message_he;
          const instName = this.bf(s, 'institution');
          const loc = this.bf(s, 'location');
          const prog = this.bf(s, 'relevant_program');
          const dm = this.bf(s, 'decision_maker');
          const fit = this.bf(s, 'fit_opportunity');
          const nextAct = this.bf(s, 'next_action');
          const notes = this.bf(s, 'notes');
          const cleanPhone = (s.verified_phone || '').split('/')[0].replace(/[^0-9+*]/g, '');

          return `
            <article class="school-card">
              <div>
                <div class="school-head">
                  <div style="display:flex;align-items:flex-start;gap:10px;min-width:0">
                    <span class="school-num">${s.record_number || s.id}</span>
                    <div style="min-width:0">
                      <h3 class="school-title">${this.escapeHtml(instName)}</h3>
                      ${loc ? `<div class="school-loc">📍 ${this.escapeHtml(loc)}</div>` : ''}
                    </div>
                  </div>
                  ${this.formatStatusBadge(s.status)}
                </div>

                <div class="school-body">
                  ${(s.verified_email || s.verified_phone || s.website) ? `
                    <div class="quick-contacts-row">
                      ${cleanPhone ? `<a href="tel:${this.escapeHtml(cleanPhone)}" class="q-chip" dir="ltr">📞 ${this.escapeHtml(s.verified_phone)}</a>` : ''}
                      ${s.verified_email ? `<button type="button" class="q-chip" dir="ltr" onclick="window.app.copySchoolEmail(${s.id})">✉️ ${this.escapeHtml(s.verified_email)}</button>` : ''}
                      ${s.website ? `<a href="${this.escapeHtml(s.website)}" target="_blank" rel="noopener noreferrer" class="q-chip" style="color:var(--electric-600)">${this.escapeHtml(this.t('openWebsiteBtn'))} ↗</a>` : ''}
                    </div>
                  ` : ''}

                  ${prog ? `
                    <div style="font-size:13px">
                      <span class="task-callout-label">${this.escapeHtml(this.t('colProgram'))}</span>
                      ${this.escapeHtml(prog)}
                    </div>
                  ` : ''}

                  ${dm ? `
                    <div style="font-size:13px">
                      <span class="task-callout-label">${this.escapeHtml(this.t('colDecisionMaker'))}</span>
                      <strong>${this.escapeHtml(dm)}</strong>
                    </div>
                  ` : ''}

                  ${fit ? `
                    <div class="task-callout deliverable">
                      <span class="task-callout-label">${this.escapeHtml(this.t('colFit'))}</span>
                      ${this.escapeHtml(fit)}
                    </div>
                  ` : ''}

                  ${nextAct ? `
                    <div class="task-callout">
                      <span class="task-callout-label">${this.escapeHtml(this.t('colNextAction'))}</span>
                      <strong>${this.escapeHtml(nextAct)}</strong>
                    </div>
                  ` : ''}

                  ${s.record_type === 'prospect' ? `
                    <details class="msg-accordion">
                      <summary>
                        <span>✉️ ${this.escapeHtml(this.t('toggleMsgSummary'))}</span>
                        <span>▾</span>
                      </summary>
                      <div class="msg-accordion-content">
                        <div style="display:flex;align-items:center;justify-content:space-between">
                          <div class="msg-lang-tabs">
                            <button type="button" class="msg-lang-tab ${activeMsgTab === 'he' ? 'active' : ''}" onclick="window.app.setSchoolMsgTab(${s.id}, 'he')">עברית</button>
                            <button type="button" class="msg-lang-tab ${activeMsgTab === 'en' ? 'active' : ''}" onclick="window.app.setSchoolMsgTab(${s.id}, 'en')">English</button>
                          </div>
                        </div>
                        <div class="msg-text-box" dir="${activeMsgTab === 'he' ? 'rtl' : 'ltr'}">${this.escapeHtml(currentDraft)}</div>
                      </div>
                    </details>
                  ` : ''}

                  ${notes ? `
                    <div style="font-size:11.8px;color:var(--text-muted)">${this.escapeHtml(notes)}</div>
                  ` : ''}
                </div>
              </div>

              <div class="school-foot">
                ${s.outreach_message_he ? `<button type="button" class="btn btn-sm btn-outline" onclick="window.app.copySchoolMsg(${s.id}, 'he')">${this.escapeHtml(this.t('copyMessageHeBtn'))}</button>` : ''}
                ${s.outreach_message_en ? `<button type="button" class="btn btn-sm btn-outline" onclick="window.app.copySchoolMsg(${s.id}, 'en')">${this.escapeHtml(this.t('copyMessageEnBtn'))}</button>` : ''}
                ${s.status.toLowerCase() === 'ready for approval' ? `
                  <button type="button" class="btn btn-sm btn-emerald" onclick="window.app.quickApproveSchool(${s.id})">${this.escapeHtml(this.t('approveBtn'))}</button>
                ` : ''}
                <button type="button" class="btn btn-sm btn-primary" onclick="window.app.openSchoolModal(${s.id})">✏️ ${this.escapeHtml(this.t('editBtn'))}</button>
              </div>
            </article>
          `;
        }).join('')}
      </div>
    `;
  }

  setSchoolTypeFilter(type) {
    this.schoolRecordTypeFilter = type;
    this.renderCurrentSection();
  }

  setSchoolSearch(val) {
    this.schoolSearch = val;
    this.renderCurrentSection();
  }

  setSchoolMsgTab(schoolId, lang) {
    this.schoolMsgTab[schoolId] = lang;
    this.renderCurrentSection();
  }

  copySchoolEmail(id) {
    const s = this.data.schools.find(item => item.id === id);
    if (s && s.verified_email) this.copyText(s.verified_email, 'copiedEmailToast');
  }

  copySchoolMsg(id, lang) {
    const s = this.data.schools.find(item => item.id === id);
    if (!s) return;
    const text = lang === 'en' ? s.outreach_message_en : s.outreach_message_he;
    this.copyText(text, 'copiedMsgToast');
  }

  async quickApproveSchool(id) {
    try {
      const res = await fetch(`api/schools/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'Approved' })
      });
      if (!res.ok) throw new Error('Static mode');
      this.data = await res.json();
    } catch {
      const s = this.data.schools.find(x => x.id === id);
      if (s) s.status = 'Approved';
      this.recomputeSummary();
    }
    localStorage.setItem('lev_ari_local_backup', JSON.stringify(this.data));
    this.updateNavBadges();
    this.renderCurrentSection();
    this.showToast(this.t('approvedToast'));
  }

  /* =========================================================================
   * 4. MOBILE-FIRST ATHLETIC GROUPS (COMPACT SLOT CARDS)
   * ========================================================================= */
  renderAthleticSection() {
    const { athleticGroups } = this.data;

    const filtered = athleticGroups.filter(g => {
      if (this.athleticCategoryFilter !== 'all' && g.category.toLowerCase() !== this.athleticCategoryFilter.toLowerCase()) {
        return false;
      }
      if (this.athleticSearch) {
        const q = this.athleticSearch.toLowerCase();
        const hay = `${g.category} ${g.club_organization_he} ${g.club_organization_en} ${g.location_he} ${g.location_en} ${g.decision_maker_he} ${g.decision_maker_en} ${g.contact_details}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    const cats = [
      { key: 'Running', label: this.t('catRunning') },
      { key: 'Cycling', label: this.t('catCycling') },
      { key: 'Triathlon', label: this.t('catTriathlon') },
      { key: 'all', label: `${this.t('filterAll')} (30)` }
    ];

    return `
      <div class="filter-bar">
        <div class="pills-scroll">
          ${cats.map(c => `
            <button type="button" class="pill-btn ${this.athleticCategoryFilter === c.key ? 'active' : ''}" onclick="window.app.setAthleticCategory('${c.key}')">
              ${this.escapeHtml(c.label)}
            </button>
          `).join('')}
        </div>

        <div class="search-actions-row">
          <input type="search" class="search-box" placeholder="${this.escapeHtml(this.t('searchPlaceholder'))}" value="${this.escapeHtml(this.athleticSearch)}" oninput="window.app.setAthleticSearch(this.value)" />
          <button type="button" class="btn btn-primary" onclick="window.app.openAthleticModal()">${this.escapeHtml(this.t('addGroupBtn'))}</button>
        </div>
      </div>

      <div class="cards-list">
        ${filtered.map(g => {
          const clubName = this.bf(g, 'club_organization').trim();
          if (!clubName) {
            // Compact 1-line mobile card for unresearched target slots
            return `
              <div class="athletic-slot-card">
                <div style="display:flex;align-items:center;gap:10px;min-width:0">
                  <span class="school-num" style="background:var(--bg-muted);color:var(--text-secondary)">#${g.slot_number}</span>
                  <div>
                    <div style="font-weight:800;font-size:13.8px;color:var(--navy-900)">${this.escapeHtml(this.formatCategoryText(g.category))} – ${this.escapeHtml(this.t('statusNotResearched'))}</div>
                    <div style="font-size:12px;color:var(--text-muted)">${this.escapeHtml(this.bf(g, 'next_action'))}</div>
                  </div>
                </div>
                <button type="button" class="btn btn-sm btn-outline" onclick="window.app.openAthleticModal(${g.id})">${this.escapeHtml(this.t('populateSlotBtn'))}</button>
              </div>
            `;
          }

          return `
            <article class="task-card">
              <div class="task-card-top">
                <div class="task-id-group">
                  <span class="school-num">#${g.slot_number}</span>
                  <span class="priority-badge">${this.escapeHtml(this.formatCategoryText(g.category))}</span>
                </div>
                ${this.formatStatusBadge(g.status)}
              </div>
              <div>
                <h3 class="task-title">${this.escapeHtml(clubName)}</h3>
                ${this.bf(g, 'location') ? `<div class="school-loc">📍 ${this.escapeHtml(this.bf(g, 'location'))}</div>` : ''}
              </div>
              ${this.bf(g, 'decision_maker') ? `<div style="font-size:13px"><strong>${this.escapeHtml(this.t('colHeadCoach'))}:</strong> ${this.escapeHtml(this.bf(g, 'decision_maker'))}</div>` : ''}
              ${g.contact_details ? `<div style="font-size:13px"><strong>${this.escapeHtml(this.t('colContactDetails'))}:</strong> ${this.escapeHtml(g.contact_details)}</div>` : ''}
              <div class="task-card-foot">
                ${g.website_social ? `<a href="${this.escapeHtml(g.website_social)}" target="_blank" rel="noopener noreferrer" class="btn btn-sm btn-outline">${this.escapeHtml(this.t('openWebsiteBtn'))} ↗</a>` : '<span></span>'}
                <button type="button" class="btn btn-sm btn-primary" onclick="window.app.openAthleticModal(${g.id})">✏️ ${this.escapeHtml(this.t('editBtn'))}</button>
              </div>
            </article>
          `;
        }).join('')}
      </div>
    `;
  }

  setAthleticCategory(cat) {
    this.athleticCategoryFilter = cat;
    this.renderCurrentSection();
  }

  setAthleticSearch(val) {
    this.athleticSearch = val;
    this.renderCurrentSection();
  }

  /* =========================================================================
   * MODALS (BOTTOM SHEET ON MOBILE)
   * ========================================================================= */
  openModal(title, bodyHtml) {
    document.getElementById('modal-title').textContent = title;
    document.getElementById('modal-body').innerHTML = bodyHtml;
    document.getElementById('modal-backdrop').classList.remove('hidden');
  }

  closeModal() {
    document.getElementById('modal-backdrop').classList.add('hidden');
  }

  handleBackdropClick(e) {
    if (e.target.id === 'modal-backdrop') this.closeModal();
  }

  openTaskModal(id = null) {
    const task = id ? this.data.tasks.find(t => t.id === id) : null;
    const title = task ? `#${task.task_number} ${this.bf(task, 'task')}` : this.t('addTaskBtn');
    const currentOwner = task ? this.getOwnerKey(task) : 'maccabi';

    this.openModal(title, `
      <form onsubmit="window.app.saveTaskForm(event, ${id || 'null'})">
        <div class="form-grid">
          <div class="form-group full-width">
            <label class="form-label">${this.escapeHtml(this.t('selectOwnerLabel'))}</label>
            <div class="owner-selector-group">
              <label class="owner-radio-label">
                <input type="radio" name="owner_key" value="ofek" ${currentOwner === 'ofek' ? 'checked' : ''} />
                <span>👤 ${this.escapeHtml(this.t('ownerOfek'))}</span>
              </label>
              <label class="owner-radio-label">
                <input type="radio" name="owner_key" value="maccabi" ${currentOwner === 'maccabi' ? 'checked' : ''} />
                <span>👤 ${this.escapeHtml(this.t('ownerMaccabi'))}</span>
              </label>
            </div>
          </div>

          <div class="form-group">
            <label class="form-label">${this.escapeHtml(this.t('colPriority'))}</label>
            <select name="priority" class="form-control">
              ${['P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7'].map(p => `
                <option value="${p}" ${(task ? task.priority : 'P2') === p ? 'selected' : ''}>${p}</option>
              `).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">${this.escapeHtml(this.t('colStatus'))}</label>
            <select name="status" class="form-control">
              ${['Not started', 'In progress', 'On hold', 'Ready for approval', 'Completed'].map(st => `
                <option value="${st}" ${task && task.status.toLowerCase() === st.toLowerCase() ? 'selected' : ''}>${this.escapeHtml(this.formatStatusText(st))}</option>
